mapper.select:
SELECT * FROM (
    SELECT 'WORK' type,l.id,l.work_date record_date,l.zone_id,z.name zone_name,z.active_yn zone_active_yn,'작업' primary_label,COALESCE(w.name,'미지정') primary_value,l.created_by,u.display_name created_by_name,l.created_role,l.farmer_confirm_status,l.created_at FROM work_log l LEFT JOIN farm_zone z ON z.id=l.zone_id LEFT JOIN work_type w ON w.id=l.work_type_id LEFT JOIN users u ON u.id=l.created_by WHERE l.farm_id=#{farmId} AND l.care_assignment_id=#{assignmentId} AND l.deleted_at IS NULL
    UNION ALL SELECT 'PEST_CONTROL',l.id,l.apply_date,l.zone_id,z.name,z.active_yn,'방제',l.chemical_name,l.created_by,u.display_name,l.created_role,l.farmer_confirm_status,l.created_at FROM pest_control_log l LEFT JOIN farm_zone z ON z.id=l.zone_id LEFT JOIN users u ON u.id=l.created_by WHERE l.farm_id=#{farmId} AND l.care_assignment_id=#{assignmentId} AND l.deleted_at IS NULL
    UNION ALL SELECT 'HARVEST',l.id,l.harvest_date,l.zone_id,z.name,z.active_yn,'수확',CONCAT(l.quantity,' ',l.unit),l.created_by,u.display_name,l.created_role,l.farmer_confirm_status,l.created_at FROM harvest_log l LEFT JOIN farm_zone z ON z.id=l.zone_id LEFT JOIN users u ON u.id=l.created_by WHERE l.farm_id=#{farmId} AND l.care_assignment_id=#{assignmentId} AND l.deleted_at IS NULL
    UNION ALL SELECT 'SALES',l.id,l.sales_date,NULL,NULL,NULL,'판매',COALESCE(l.item_name,CONCAT(l.quantity,' ',l.unit)),l.created_by,u.display_name,l.created_role,l.farmer_confirm_status,l.created_at FROM sales_log l LEFT JOIN users u ON u.id=l.created_by WHERE l.farm_id=#{farmId} AND l.care_assignment_id=#{assignmentId} AND l.deleted_at IS NULL
  ) r ORDER BY record_date DESC,id DESC LIMIT #{size}
